<script>
$(function()
{
	$(".ui-iframe").click(function()
	{
		if($(this).hasClass("disabled"))
		{
			return false;
		}
		event.preventDefault();
		var url=$(this).attr("href") || $(this).data("url") || document.location;
		var title=$(this).data("title") || $(this).html() || '操作提示';
		var size=$(this).data("size") || '80%:80%';
		var foot=$(this).attr("data-foot") || '1';
		var footer=(foot=='1')?true:false;
		var data=size.split(":");
		var width=data[0];
		var height=data[1];
		$.dialogbox(
		{
			title:title,
			text:url,
			width:width,
			height:height,
			footer:footer,
			type:3,
			ok:function(e)
			{
				e.iframe().contents().find("#sdcms-submit").click();
			}
		});
	});
	$(".ui-action").click(function()
	{
		if($(this).hasClass("disabled") || $(this).hasClass("ui-disabled"))
		{
			return false;
		}
		event.preventDefault();
		var type=$(this).data("type") || 'del';
		var url=$(this).attr("href") || $(this).data("url")  || document.location;
		var backurl=$(this).data("back") || document.location;
		var title=$(this).data("title") || '确定要删除？不可恢复！';
		var data=$(this).data("data") || '';
		var tips=$(this).data("tips") || '';
		var theme='ui-btn-blue';
		$.dialog(
		{
			title:"操作提示",
			text:title,
			oktheme:theme,
			ok:function(e)
			{
				if(tips!='')
				{
					sdcms.loading(tips);
				}
				$.ajax(
				{
                    url:url,
					type:'post',
					dataType:'json',
					error:function(e){alert(e.responseText);},
					data:data,
                    success:function(d)
                    {
                        e.close();
                        if(d.state=='success')
                        {
                            sdcms.success(d.msg);
                            setTimeout(function(){location.href=backurl;},1000);
                        }
                        else
                        {
                            sdcms.error(d.msg);
                        }
                    }
                });
			}
		});
    });
	$(".view").click(function()
	{
		event.preventDefault();
		var url=$(this).attr("href");
		$.ajax(
		{
			type:'get',
			cache:false,
			url:url,
			error:function(e){alert(e.responseText);},
			success:function(d)
			{
				$.dialog(
				{
					title:"查看原因",
					text:d,
					ok:function(e)
					{
						e.close();
					}
				});
			}
		})
	});
})
</script>
</body>
</html>